function cloneArray(value) {
  return Array.isArray(value) ? value.map(cloneValue) : value;
}

function cloneObject(value) {
  if (!value || typeof value !== 'object') {
    return value;
  }
  const entries = Object.entries(value).map(([key, entryValue]) => [key, cloneValue(entryValue)]);
  return Object.fromEntries(entries);
}

function cloneValue(value) {
  if (Array.isArray(value)) {
    return cloneArray(value);
  }
  if (value && typeof value === 'object') {
    return cloneObject(value);
  }
  return value;
}

function mergeThemeSection(baseSection, overrideSection) {
  if (!overrideSection) {
    return cloneObject(baseSection);
  }
  const merged = cloneObject(baseSection);
  for (const [key, value] of Object.entries(overrideSection)) {
    if (value && typeof value === 'object' && !Array.isArray(value) && merged[key] && typeof merged[key] === 'object' && !Array.isArray(merged[key])) {
      merged[key] = mergeThemeSection(merged[key], value);
      continue;
    }
    merged[key] = cloneValue(value);
  }
  return merged;
}

function getThemePreset(theme = defaultThemePresetName) {
  if (typeof theme === 'string') {
    return cloneObject(themePresets[theme] || themePresets[defaultThemePresetName]);
  }

  const baseTheme = themePresets[defaultThemePresetName];
  return {
    scene: mergeThemeSection(baseTheme.scene, theme?.scene),
    ui: mergeThemeSection(baseTheme.ui, theme?.ui),
    materials: mergeThemeSection(baseTheme.materials, theme?.materials),
    chemistry: mergeThemeSection(baseTheme.chemistry, theme?.chemistry),
    apparatusVariants: mergeThemeSection(baseTheme.apparatusVariants, theme?.apparatusVariants),
  };
}

function resolveHud(hud = {}) {
  const ids = {
    canvas: hud.canvasId || 'stage',
    statusText: hud.statusTextId || 'statusText',
    statusSub: hud.statusSubId || 'statusSub',
    primaryAction: hud.primaryActionId || hud.primaryButtonId || 'primaryAction',
    reset: hud.resetId || 'resetBtn',
    labelsToggle: hud.labelsToggleId || 'labelsToggle',
    root: hud.rootId || null,
  };

  return {
    ids,
    canvas: hud.canvas || document.getElementById(ids.canvas),
    root: hud.root || (ids.root ? document.getElementById(ids.root) : document.documentElement),
    statusText: hud.statusText || document.getElementById(ids.statusText),
    statusSub: hud.statusSub || document.getElementById(ids.statusSub),
    primaryAction: hud.primaryAction || hud.primaryButton || document.getElementById(ids.primaryAction),
    reset: hud.reset || document.getElementById(ids.reset),
    labelsToggle: hud.labelsToggle || document.getElementById(ids.labelsToggle),
  };
}

function applyUiTheme(hud, theme) {
  const root = hud.root || document.documentElement;
  if (!root?.style || !theme?.ui) {
    return;
  }
  root.style.setProperty('--panel', theme.ui.panel);
  root.style.setProperty('--panel-soft', theme.ui.panelSoft);
  root.style.setProperty('--border', theme.ui.border);
  root.style.setProperty('--text', theme.ui.text);
  root.style.setProperty('--muted', theme.ui.muted);
  root.style.setProperty('--accent', theme.ui.accent);
  root.style.setProperty('--warm', theme.ui.warm);
  root.style.setProperty('--button-primary', theme.ui.buttonPrimary);
  root.style.setProperty('--button-secondary', theme.ui.buttonSecondary);
}

function createSceneShell({
  canvas,
  theme,
  cameraPreset,
  controlsPreset = {},
  hud,
  verifier,
} = {}) {
  const resolvedHud = resolveHud({ ...hud, canvas });
  const resolvedCanvas = resolvedHud.canvas;
  if (!resolvedCanvas) {
    throw new Error('createSceneShell requires a canvas or HUD canvas reference');
  }

  const resolvedTheme = getThemePreset(theme);
  const resolvedCameraPreset = getCameraPreset(cameraPreset);
  const stageTheme = resolvedTheme.scene || {};
  const benchTopSize = stageTheme.benchTopSize || [12.8, 0.34, 5.8];
  const benchTopY = stageTheme.benchTopY ?? 1.32;
  const benchLegSize = stageTheme.benchLegSize || [0.35, 2.6, 0.35];
  const benchLegOffsets = stageTheme.benchLegOffsets || [[-5.8, -2.4], [5.8, -2.4], [-5.8, 2.4], [5.8, 2.4]];
  const floorRadius = stageTheme.floorRadius || 24;
  const roomRadius = stageTheme.roomRadius || 40;
  const stagePadConfig = stageTheme.stagePad || { visible: false };
  const renderer = new THREE.WebGLRenderer({ canvas: resolvedCanvas, antialias: true, alpha: true });
  renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
  renderer.setSize(window.innerWidth, window.innerHeight);
  renderer.outputColorSpace = THREE.SRGBColorSpace;
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;

  const scene = new THREE.Scene();
  const camera = new THREE.PerspectiveCamera(
    resolvedCameraPreset.fov,
    window.innerWidth / window.innerHeight,
    resolvedCameraPreset.near,
    resolvedCameraPreset.far,
  );
  camera.position.fromArray(resolvedCameraPreset.position);

  const OrbitControlsImpl = globalThis.OrbitControls || (typeof OrbitControls !== 'undefined' ? OrbitControls : null);
  if (!OrbitControlsImpl) {
    throw new Error('createSceneShell requires OrbitControls to be available (set globalThis.OrbitControls)');
  }

  const controls = new OrbitControlsImpl(camera, renderer.domElement);
  controls.enableDamping = true;
  controls.target.fromArray(resolvedCameraPreset.target);
  Object.assign(controls, {
    minDistance: resolvedCameraPreset.minDistance,
    maxDistance: resolvedCameraPreset.maxDistance,
    minPolarAngle: resolvedCameraPreset.minPolarAngle,
    maxPolarAngle: resolvedCameraPreset.maxPolarAngle,
    ...controlsPreset,
  });
  controls.update();

  const lights = {
    ambient: new THREE.HemisphereLight(),
    key: new THREE.DirectionalLight(),
    rim: new THREE.PointLight(),
    warm: null,
  };

  lights.key.castShadow = true;
  lights.key.shadow.mapSize.set(2048, 2048);
  lights.key.shadow.camera.left = -16;
  lights.key.shadow.camera.right = 16;
  lights.key.shadow.camera.top = 16;
  lights.key.shadow.camera.bottom = -16;

  const room = new THREE.Mesh(
    new THREE.SphereGeometry(roomRadius, 42, 28),
    new THREE.MeshBasicMaterial({ side: THREE.BackSide }),
  );

  const floor = new THREE.Mesh(
    new THREE.CircleGeometry(floorRadius, 72),
    new THREE.MeshStandardMaterial({ roughness: 0.96, metalness: 0.04 }),
  );
  floor.rotation.x = -Math.PI / 2;
  floor.receiveShadow = true;

  const bench = new THREE.Group();
  const benchTop = new THREE.Mesh(
    new THREE.BoxGeometry(benchTopSize[0], benchTopSize[1], benchTopSize[2]),
    new THREE.MeshStandardMaterial({ roughness: 0.86, metalness: 0.06 }),
  );
  benchTop.position.y = benchTopY;
  benchTop.castShadow = true;
  benchTop.receiveShadow = true;
  bench.add(benchTop);

  const legGeometry = new THREE.BoxGeometry(benchLegSize[0], benchLegSize[1], benchLegSize[2]);
  const legMaterial = new THREE.MeshStandardMaterial({ roughness: 0.72, metalness: 0.24 });
  for (const [x, z] of benchLegOffsets) {
    const leg = new THREE.Mesh(legGeometry, legMaterial);
    leg.position.set(x, (benchTopY - benchTopSize[1] * 0.5) - benchLegSize[1] * 0.5, z);
    leg.castShadow = true;
    leg.receiveShadow = true;
    bench.add(leg);
  }

  let stagePad = null;
  if (stagePadConfig.visible) {
    stagePad = new THREE.Mesh(
      new THREE.BoxGeometry(stagePadConfig.width || 9.6, stagePadConfig.height || 0.08, stagePadConfig.depth || 2),
      new THREE.MeshStandardMaterial({ color: stagePadConfig.color || 0x111824, roughness: 0.9, metalness: 0.02 }),
    );
    stagePad.position.set(0, stagePadConfig.y ?? (benchTopY + benchTopSize[1] * 0.5 + (stagePadConfig.height || 0.08) * 0.5), 0);
    stagePad.castShadow = true;
    stagePad.receiveShadow = true;
    stagePad.name = 'stagePad';
    bench.add(stagePad);
  }

  let activeTheme = resolvedTheme;
  scene.add(lights.ambient, lights.key, lights.rim, room, floor, bench);

  function applyTheme(nextTheme = resolvedTheme) {
    activeTheme = getThemePreset(nextTheme);
    const sceneTheme = activeTheme.scene;

    scene.background = new THREE.Color(sceneTheme.background);
    scene.fog = sceneTheme.fog
      ? new THREE.Fog(sceneTheme.fog.color, sceneTheme.fog.near, sceneTheme.fog.far)
      : null;
    renderer.toneMapping = sceneTheme.toneMapping;
    renderer.toneMappingExposure = sceneTheme.rendererExposure;

    lights.ambient.color.setHex(sceneTheme.ambientLight.skyColor);
    lights.ambient.groundColor.setHex(sceneTheme.ambientLight.groundColor);
    lights.ambient.intensity = sceneTheme.ambientLight.intensity;

    lights.key.color.setHex(sceneTheme.keyLight.color);
    lights.key.intensity = sceneTheme.keyLight.intensity;
    lights.key.position.fromArray(sceneTheme.keyLight.position);

    lights.rim.color.setHex(sceneTheme.rimLight.color);
    lights.rim.intensity = sceneTheme.rimLight.intensity;
    lights.rim.distance = sceneTheme.rimLight.distance;
    lights.rim.decay = sceneTheme.rimLight.decay;
    lights.rim.position.fromArray(sceneTheme.rimLight.position);

    if (sceneTheme.warmLight) {
      if (!lights.warm) {
        lights.warm = new THREE.PointLight();
        scene.add(lights.warm);
      }
      lights.warm.color.setHex(sceneTheme.warmLight.color);
      lights.warm.intensity = sceneTheme.warmLight.intensity;
      lights.warm.distance = sceneTheme.warmLight.distance;
      lights.warm.decay = sceneTheme.warmLight.decay;
      lights.warm.position.fromArray(sceneTheme.warmLight.position);
    } else if (lights.warm) {
      scene.remove(lights.warm);
      lights.warm = null;
    }

    room.material.color.setHex(sceneTheme.room);
    floor.material.color.setHex(sceneTheme.floor);
    benchTop.material.color.setHex(sceneTheme.bench);
    legMaterial.color.setHex(sceneTheme.benchLeg);
    if (stagePad && sceneTheme.stagePad?.color != null) {
      stagePad.material.color.setHex(sceneTheme.stagePad.color);
    }

    applyUiTheme(resolvedHud, activeTheme);
    return activeTheme;
  }

  function resize(width = window.innerWidth, height = window.innerHeight) {
    camera.aspect = width / Math.max(height, 1);
    camera.updateProjectionMatrix();
    renderer.setSize(width, height, false);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    return { width, height };
  }

  const handleResize = () => resize(window.innerWidth, window.innerHeight);
  window.addEventListener('resize', handleResize);

  function installHarness(overrides = {}) {
    return installCoursewareTestHarness({
      state: overrides.state ?? verifier?.state ?? {},
      mapState: overrides.mapState ?? verifier?.mapState ?? ((state) => state),
      getVerifierMeta: overrides.getVerifierMeta ?? verifier?.getVerifierMeta,
      getGoldenPath: overrides.getGoldenPath ?? verifier?.getGoldenPath,
      getDragPath: overrides.getDragPath ?? verifier?.getDragPath,
      runVerifierStep: overrides.runVerifierStep ?? verifier?.runVerifierStep,
    });
  }

  applyTheme(resolvedTheme);
  resize();

  return {
    renderer,
    scene,
    camera,
    controls,
    lights,
    hud: resolvedHud,
    bench,
    floor,
    room,
    stagePad,
    theme: activeTheme,
    resize,
    applyTheme,
    installHarness,
    dispose() {
      window.removeEventListener('resize', handleResize);
      controls.dispose();
      renderer.dispose();
    },
  };
}

function clamp01(value) {
  return Math.max(0, Math.min(1, value));
}

function lerp(a, b, t) {
  return a + (b - a) * t;
}

function smoothstep01(t) {
  const value = clamp01(t);
  return value * value * (3 - 2 * value);
}

function segment(t, start, end) {
  if (end === start) {
    return t >= end ? 1 : 0;
  }
  return clamp01((t - start) / (end - start));
}

function sequenceProgress(t, segments) {
  return segments.map(({ start, end, easing }) => {
    const value = segment(t, start, end);
    return easing ? easing(value) : value;
  });
}

function getAnchorMotionAnchor(target, anchorName = null) {
  if (!target) {
    return null;
  }
  if (anchorName && target.anchors?.[anchorName]) {
    return target.anchors[anchorName];
  }
  if (typeof target.getWorldPosition === 'function' || target.isVector3) {
    return target;
  }
  return target.group || null;
}

function getAnchorMotionWorldPoint(target, out = new THREE.Vector3()) {
  if (typeof target?.getWorldPosition === 'function') {
    return target.getWorldPosition(out);
  }
  if (target?.isVector3) {
    return out.copy(target);
  }
  return out.set(0, 0, 0);
}

function toAnchorMotionParentLocal(parent, worldPoint, out = new THREE.Vector3()) {
  out.copy(worldPoint);
  if (typeof parent?.worldToLocal === 'function') {
    parent.worldToLocal(out);
  }
  return out;
}

function cloneAnchorMotionRotation(rotation) {
  return new THREE.Euler(rotation?.x || 0, rotation?.y || 0, rotation?.z || 0, rotation?.order || 'XYZ');
}

function resolveAnchorMotionRotation(rotation) {
  if (!rotation) {
    return null;
  }
  if (rotation.isEuler) {
    return cloneAnchorMotionRotation(rotation);
  }
  if (Array.isArray(rotation)) {
    return new THREE.Euler(rotation[0] || 0, rotation[1] || 0, rotation[2] || 0, rotation[3] || 'XYZ');
  }
  return new THREE.Euler(rotation.x || 0, rotation.y || 0, rotation.z || 0, rotation.order || 'XYZ');
}

function computeAnchorPlacementPose({
  source,
  sourceAnchor = 'interactionZone',
  target,
  targetAnchor = 'effectOrigin',
  parent = null,
  offset = [0, 0, 0],
  rotation = null,
} = {}) {
  const sourceObject = source?.group || source;
  const sourceAnchorObject = getAnchorMotionAnchor(source, sourceAnchor);
  const targetAnchorObject = getAnchorMotionAnchor(target, targetAnchor);
  if (!sourceObject || !sourceAnchorObject || !targetAnchorObject) {
    throw new Error('computeAnchorPlacementPose requires source object, source anchor, and target anchor');
  }

  const originalPosition = sourceObject.position.clone();
  const originalRotation = cloneAnchorMotionRotation(sourceObject.rotation);
  const placementRotation = resolveAnchorMotionRotation(rotation) || originalRotation.clone();

  sourceObject.rotation.copy(placementRotation);
  sourceObject.updateMatrixWorld(true);

  const targetWorld = getAnchorMotionWorldPoint(targetAnchorObject, new THREE.Vector3());
  const targetLocal = toAnchorMotionParentLocal(parent, targetWorld, new THREE.Vector3()).add(
    new THREE.Vector3(offset[0] || 0, offset[1] || 0, offset[2] || 0),
  );
  const sourceWorld = getAnchorMotionWorldPoint(sourceAnchorObject, new THREE.Vector3());
  const sourceLocal = toAnchorMotionParentLocal(parent, sourceWorld, new THREE.Vector3());
  const position = sourceObject.position.clone().add(targetLocal.sub(sourceLocal));

  sourceObject.position.copy(originalPosition);
  sourceObject.rotation.copy(originalRotation);
  sourceObject.updateMatrixWorld(true);

  return { position, rotation: placementRotation };
}

function applyAnchorPlacement(options = {}) {
  const sourceObject = options.source?.group || options.source;
  const pose = computeAnchorPlacementPose(options);
  sourceObject.position.copy(pose.position);
  sourceObject.rotation.copy(pose.rotation);
  sourceObject.updateMatrixWorld(true);
  return pose;
}

function createGuidedAnchorMotion({
  source,
  sourceAnchor,
  target,
  targetAnchor,
  parent = null,
  offset = [0, 0, 0],
  rotation = null,
  duration = 1.2,
  easing = (value) => THREE.MathUtils.smoothstep(value, 0, 1),
  dragController = null,
  onStart,
  onUpdate,
  onComplete,
} = {}) {
  const sourceObject = source?.group || source;
  const state = {
    active: false,
    t: 0,
    duration,
    progress: 0,
    fromPosition: new THREE.Vector3(),
    toPosition: new THREE.Vector3(),
    fromRotation: new THREE.Euler(),
    toRotation: new THREE.Euler(),
  };

  function start(extra = {}) {
    if (!sourceObject || state.active) {
      return false;
    }
    const pose = computeAnchorPlacementPose({
      source,
      sourceAnchor,
      target,
      targetAnchor,
      parent,
      offset,
      rotation,
      ...extra,
    });
    state.active = true;
    state.t = 0;
    state.progress = 0;
    state.fromPosition.copy(sourceObject.position);
    state.toPosition.copy(pose.position);
    state.fromRotation.copy(sourceObject.rotation);
    state.toRotation.copy(pose.rotation);
    dragController?.setEnabled?.(false);
    onStart?.({ state, pose });
    return true;
  }

  function update(dt = 1 / 60) {
    if (!state.active || !sourceObject) {
      return state;
    }

    state.t += dt;
    state.progress = Math.min(1, state.t / Math.max(state.duration, 0.001));
    const eased = easing(state.progress);
    sourceObject.position.lerpVectors(state.fromPosition, state.toPosition, eased);
    sourceObject.rotation.x = THREE.MathUtils.lerp(state.fromRotation.x, state.toRotation.x, eased);
    sourceObject.rotation.y = THREE.MathUtils.lerp(state.fromRotation.y, state.toRotation.y, eased);
    sourceObject.rotation.z = THREE.MathUtils.lerp(state.fromRotation.z, state.toRotation.z, eased);
    onUpdate?.({ state, eased });

    if (state.progress >= 1) {
      state.active = false;
      dragController?.setEnabled?.(true);
      sourceObject.position.copy(state.toPosition);
      sourceObject.rotation.copy(state.toRotation);
      onComplete?.({ state });
    }

    return state;
  }

  function cancel({ restoreDrag = true } = {}) {
    state.active = false;
    state.t = 0;
    state.progress = 0;
    if (restoreDrag) {
      dragController?.setEnabled?.(true);
    }
    return state;
  }

  return {
    state,
    start,
    update,
    cancel,
    get active() {
      return state.active;
    },
  };
}

function createGuidedPourMotion({
  source,
  sourceAnchor,
  target,
  targetAnchor,
  parent = null,
  offset = [0, 0, 0],
  rotation = null,
  approachDuration = 0.9,
  pourDuration = 0.95,
  easing = (value) => THREE.MathUtils.smoothstep(value, 0, 1),
  dragController = null,
  stream = null,
  streamSource = null,
  streamTarget = null,
  intensityCurve = (value) => THREE.MathUtils.clamp(0.18 + (value * 0.92), 0, 1),
  successId = null,
  successBehavior = 'return-home',
  successReturnDelayMs = 0,
  onStart,
  onApproachStart,
  onApproachUpdate,
  onPourStart,
  onPourUpdate,
  onPourComplete,
  onComplete,
} = {}) {
  const sourceObject = source?.group || source;
  const state = {
    active: false,
    phase: 'idle',
    t: 0,
    progress: 0,
    approachProgress: 0,
    pourProgress: 0,
    fromPosition: new THREE.Vector3(),
    toPosition: new THREE.Vector3(),
    fromRotation: new THREE.Euler(),
    toRotation: new THREE.Euler(),
    options: {
      target,
      targetAnchor,
      offset,
      rotation,
      streamSource,
      streamTarget,
    },
  };

  function getResolvedAnchor(targetRef, anchorName = null) {
    if (!targetRef) {
      return null;
    }
    if (anchorName && targetRef.anchors?.[anchorName]) {
      return targetRef.anchors[anchorName];
    }
    if (typeof targetRef?.getWorldPosition === 'function' || targetRef?.isVector3) {
      return targetRef;
    }
    return targetRef.group || targetRef;
  }

  function resetStream() {
    stream?.reset?.();
  }

  function finishPour() {
    state.active = false;
    state.phase = 'complete';
    state.progress = 1;
    state.approachProgress = 1;
    state.pourProgress = 1;
    resetStream();
    dragController?.setEnabled?.(true);
    if (successId && dragController?.commitSuccess) {
      dragController.commitSuccess(successId, {
        successBehavior,
        successReturnDelayMs,
      });
    }
    onPourComplete?.({ state });
    onComplete?.({ state });
    return true;
  }

  function start(extra = {}) {
    if (!sourceObject || state.active) {
      return false;
    }

    state.options = {
      target: extra.target || target,
      targetAnchor: extra.targetAnchor || targetAnchor,
      offset: extra.offset || offset,
      rotation: extra.rotation || rotation,
      streamSource: extra.streamSource || streamSource,
      streamTarget: extra.streamTarget || streamTarget,
    };

    const pose = computeAnchorPlacementPose({
      source,
      sourceAnchor,
      target: state.options.target,
      targetAnchor: state.options.targetAnchor,
      parent,
      offset: state.options.offset,
      rotation: state.options.rotation,
    });

    state.active = true;
    state.phase = 'approach';
    state.t = 0;
    state.progress = 0;
    state.approachProgress = 0;
    state.pourProgress = 0;
    state.fromPosition.copy(sourceObject.position);
    state.toPosition.copy(pose.position);
    state.fromRotation.copy(sourceObject.rotation);
    state.toRotation.copy(pose.rotation);
    dragController?.setEnabled?.(false);
    onStart?.({ state, pose });
    onApproachStart?.({ state, pose });
    return true;
  }

  function update(dt = 1 / 60) {
    if (!state.active || !sourceObject) {
      return state;
    }

    if (state.phase === 'approach') {
      state.t += dt;
      state.approachProgress = Math.min(1, state.t / Math.max(approachDuration, 0.001));
      state.progress = state.approachProgress;
      const eased = easing(state.approachProgress);
      sourceObject.position.lerpVectors(state.fromPosition, state.toPosition, eased);
      sourceObject.rotation.x = THREE.MathUtils.lerp(state.fromRotation.x, state.toRotation.x, eased);
      sourceObject.rotation.y = THREE.MathUtils.lerp(state.fromRotation.y, state.toRotation.y, eased);
      sourceObject.rotation.z = THREE.MathUtils.lerp(state.fromRotation.z, state.toRotation.z, eased);
      onApproachUpdate?.({ state, eased });

      if (state.approachProgress >= 1) {
        sourceObject.position.copy(state.toPosition);
        sourceObject.rotation.copy(state.toRotation);
        state.phase = 'pour';
        state.t = 0;
        state.progress = 0;
        onPourStart?.({ state });
      }
      return state;
    }

    if (state.phase === 'pour') {
      state.t += dt;
      state.pourProgress = Math.min(1, state.t / Math.max(pourDuration, 0.001));
      state.progress = state.pourProgress;
      sourceObject.position.copy(state.toPosition);
      sourceObject.rotation.copy(state.toRotation);
      const resolvedStreamSource = getResolvedAnchor(state.options.streamSource || source, sourceAnchor);
      const resolvedStreamTarget = getResolvedAnchor(
        state.options.streamTarget
          || state.options.target?.meshes?.liquidSurface
          || state.options.target?.anchors?.pourTarget
          || state.options.target?.anchors?.mouth
          || (state.options.targetAnchor ? state.options.target : null)
          || state.options.target,
        state.options.streamTarget
          ? null
          : (state.options.target?.anchors?.pourTarget ? 'pourTarget'
            : state.options.target?.anchors?.mouth ? 'mouth' : state.options.targetAnchor),
      );
      stream?.setEndpoints?.(
        resolvedStreamSource,
        resolvedStreamTarget,
        intensityCurve(state.pourProgress),
      );
      onPourUpdate?.({ state });
      if (state.pourProgress >= 1) {
        finishPour();
      }
    }

    return state;
  }

  function cancel({ restoreDrag = true } = {}) {
    state.active = false;
    state.phase = 'idle';
    state.t = 0;
    state.progress = 0;
    state.approachProgress = 0;
    state.pourProgress = 0;
    resetStream();
    if (restoreDrag) {
      dragController?.setEnabled?.(true);
    }
    return state;
  }

  return {
    state,
    start,
    update,
    cancel,
    finish: finishPour,
    get active() {
      return state.active;
    },
  };
}

function createSequencedPourController({
  dragController = null,
  steps = [],
  isMotionActive = () => false,
  onPendingStart,
  onStepStart,
  onStepComplete,
  onStateChange,
} = {}) {
  const stepMap = new Map(
    steps
      .filter((step) => step?.stepId && step?.sourceId && step?.motion)
      .map((step) => [step.stepId, step]),
  );

  const state = {
    mode: 'idle',
    queue: [],
    pendingStepId: null,
    pendingMode: null,
    activeStepId: null,
    stagedSourceId: null,
  };

  function notifyStateChange() {
    onStateChange?.({ state });
  }

  function getStepConfig(stepId) {
    return stepMap.get(stepId) || null;
  }

  function nextQueuedStepUsesSource(sourceId) {
    const nextStepId = state.queue[0];
    if (!nextStepId) {
      return false;
    }
    return getStepConfig(nextStepId)?.sourceId === sourceId;
  }

  function canStartStep(stepId) {
    const config = getStepConfig(stepId);
    if (!config || state.pendingStepId || state.activeStepId || isMotionActive()) {
      return false;
    }
    if (!dragController?.canStartSequencedMotion) {
      return true;
    }
    return dragController.canStartSequencedMotion(config.sourceId, {
      allowStaged: state.stagedSourceId === config.sourceId,
    });
  }

  function beginStep(stepId, mode = 'manual') {
    const config = getStepConfig(stepId);
    if (!config || !canStartStep(stepId)) {
      return false;
    }
    state.pendingStepId = stepId;
    state.pendingMode = mode;
    state.mode = mode === 'autoplay' ? 'autoplay' : 'manual';
    notifyStateChange();
    onPendingStart?.({ state, config, mode });

    const started = config.motion.start(
      typeof config.startArgs === 'function' ? config.startArgs({ state, config, mode }) : (config.startArgs || {}),
    );
    if (!started) {
      state.pendingStepId = null;
      state.pendingMode = null;
      state.mode = state.queue.length ? 'autoplay' : 'idle';
      notifyStateChange();
      return false;
    }
    return true;
  }

  // Like beginStep but skips the dragController.canStartSequencedMotion check.
  // Use this when the source is being actively dragged (isAtHome === false by design).
  function beginStepFromActiveDrag(stepId) {
    const config = getStepConfig(stepId);
    if (!config || state.pendingStepId || state.activeStepId || isMotionActive()) {
      return false;
    }
    state.pendingStepId = stepId;
    state.pendingMode = 'manual';
    state.mode = 'manual';
    notifyStateChange();
    onPendingStart?.({ state, config, mode: 'manual' });
    const started = config.motion.start(
      typeof config.startArgs === 'function'
        ? config.startArgs({ state, config, mode: 'manual' })
        : (config.startArgs || {}),
    );
    if (!started) {
      state.pendingStepId = null;
      state.pendingMode = null;
      state.mode = state.queue.length ? 'autoplay' : 'idle';
      notifyStateChange();
      return false;
    }
    return true;
  }

  function activatePendingStep(sourceId = null) {
    if (!state.pendingStepId) {
      return false;
    }
    const config = getStepConfig(state.pendingStepId);
    if (!config || (sourceId && config.sourceId !== sourceId)) {
      return false;
    }
    const mode = state.pendingMode || state.mode || 'manual';
    state.activeStepId = state.pendingStepId;
    state.pendingStepId = null;
    state.pendingMode = null;
    state.stagedSourceId = config.sourceId;
    notifyStateChange();
    onStepStart?.({ state, config, mode });
    return true;
  }

  function completeActiveStep(sourceId = null) {
    if (!state.activeStepId) {
      return false;
    }
    const config = getStepConfig(state.activeStepId);
    if (!config || (sourceId && config.sourceId !== sourceId)) {
      return false;
    }

    const completedMode = state.mode;
    onStepComplete?.({ state, config, mode: completedMode });

    const keepStaged = completedMode === 'autoplay' && nextQueuedStepUsesSource(config.sourceId);
    if (keepStaged) {
      state.stagedSourceId = config.sourceId;
    } else {
      dragController?.commitSuccess?.(config.sourceId, {
        successBehavior: 'return-home',
        successReturnDelayMs: config.returnDelayMs ?? 0,
      });
      state.stagedSourceId = null;
    }

    state.activeStepId = null;
    state.mode = state.queue.length ? 'autoplay' : 'idle';
    notifyStateChange();
    return true;
  }

  function queueAutoplay(stepIds = []) {
    state.queue = stepIds.filter((stepId) => stepMap.has(stepId));
    state.mode = state.queue.length ? 'autoplay' : 'idle';
    notifyStateChange();
    return state.queue.length;
  }

  function shiftQueuedStep() {
    const nextStepId = state.queue.shift() || null;
    state.mode = state.queue.length || state.pendingStepId || state.activeStepId ? 'autoplay' : 'idle';
    notifyStateChange();
    return nextStepId;
  }

  function updateAutoplay() {
    if (!state.queue.length || state.pendingStepId || state.activeStepId || isMotionActive()) {
      return false;
    }
    const nextStepId = state.queue[0];
    if (!canStartStep(nextStepId)) {
      return false;
    }
    shiftQueuedStep();
    return beginStep(nextStepId, 'autoplay');
  }

  function reset() {
    state.mode = 'idle';
    state.queue = [];
    state.pendingStepId = null;
    state.pendingMode = null;
    state.activeStepId = null;
    state.stagedSourceId = null;
    notifyStateChange();
    return true;
  }

  return {
    state,
    getStepConfig,
    nextQueuedStepUsesSource,
    canStartStep,
    beginStep,
    beginStepFromActiveDrag,
    activatePendingStep,
    completeActiveStep,
    queueAutoplay,
    shiftQueuedStep,
    updateAutoplay,
    reset,
  };
}

function createContextualLabelPolicy({
  apparatus,
  label = {},
} = {}) {
  function show(nextLabel = label) {
    apparatus?.controllers?.setLabel?.(nextLabel);
    return true;
  }

  function hide() {
    apparatus?.controllers?.setLabel?.({});
    return true;
  }

  return { show, hide };
}

function createSpriteTexture(draw, size = 128) {
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');
  draw(ctx, size);
  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  return texture;
}

function createSoftCircleTexture({
  inner = 'rgba(255,255,255,0.95)',
  middle = 'rgba(196,239,255,0.65)',
  outer = 'rgba(127,205,255,0)',
} = {}) {
  return createSpriteTexture((ctx, size) => {
    const gradient = ctx.createRadialGradient(
      size * 0.48,
      size * 0.42,
      size * 0.06,
      size * 0.5,
      size * 0.5,
      size * 0.48,
    );
    gradient.addColorStop(0, inner);
    gradient.addColorStop(0.48, middle);
    gradient.addColorStop(1, outer);
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, size, size);
  });
}

function createParticlePool({
  parent,
  count = 96,
  texture = null,
  color = 0xffffff,
  size = 0.22,
  opacity = 0.7,
  blending = THREE.NormalBlending,
  name = 'particle-pool',
} = {}) {
  const geometry = new THREE.BufferGeometry();
  const positions = new Float32Array(count * 3);
  const scales = new Float32Array(count);
  const alphas = new Float32Array(count);
  positions.fill(9999);
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geometry.setAttribute('aScale', new THREE.BufferAttribute(scales, 1));
  geometry.setAttribute('aAlpha', new THREE.BufferAttribute(alphas, 1));

  const material = new THREE.PointsMaterial({
    map: texture,
    color,
    size,
    transparent: true,
    opacity,
    depthWrite: false,
    blending,
  });

  const points = new THREE.Points(geometry, material);
  points.name = name;
  points.frustumCulled = false;
  parent?.add(points);

  const particles = Array.from({ length: count }, () => ({
    active: false,
    life: 0,
    maxLife: 1,
    origin: new THREE.Vector3(),
    velocity: new THREE.Vector3(),
  }));

  function reset() {
    positions.fill(9999);
    scales.fill(0);
    alphas.fill(0);
    for (const particle of particles) {
      particle.active = false;
      particle.life = 0;
      particle.maxLife = 1;
      particle.origin.set(0, 0, 0);
      particle.velocity.set(0, 0, 0);
    }
    geometry.attributes.position.needsUpdate = true;
    geometry.attributes.aScale.needsUpdate = true;
    geometry.attributes.aAlpha.needsUpdate = true;
  }

  function spawn({
    origin = new THREE.Vector3(),
    spread = new THREE.Vector3(0.2, 0.2, 0.2),
    velocity = new THREE.Vector3(0.1, 0.5, 0.1),
    lifetime = [0.5, 1.1],
  } = {}) {
    const particle = particles.find((item) => !item.active);
    if (!particle) {
      return null;
    }
    particle.active = true;
    particle.life = 0;
    particle.maxLife = THREE.MathUtils.randFloat(lifetime[0], lifetime[1]);
    particle.origin.copy(origin).add(new THREE.Vector3(
      THREE.MathUtils.randFloatSpread(spread.x),
      THREE.MathUtils.randFloatSpread(spread.y),
      THREE.MathUtils.randFloatSpread(spread.z),
    ));
    particle.velocity.set(
      THREE.MathUtils.randFloatSpread(velocity.x),
      velocity.y + Math.random() * velocity.y,
      THREE.MathUtils.randFloatSpread(velocity.z),
    );
    return particle;
  }

  function update(dt = 1 / 60, behavior = null) {
    for (let index = 0; index < particles.length; index += 1) {
      const particle = particles[index];
      const ix = index * 3;
      if (!particle.active) {
        positions[ix] = 9999;
        positions[ix + 1] = 9999;
        positions[ix + 2] = 9999;
        scales[index] = 0;
        alphas[index] = 0;
        continue;
      }
      particle.life += dt;
      const t = particle.life / Math.max(particle.maxLife, 0.001);
      if (t >= 1) {
        particle.active = false;
        positions[ix] = 9999;
        positions[ix + 1] = 9999;
        positions[ix + 2] = 9999;
        scales[index] = 0;
        alphas[index] = 0;
        continue;
      }
      if (behavior) {
        behavior(particle, t, index);
      } else {
        particle.origin.addScaledVector(particle.velocity, dt);
        scales[index] = 1 - t;
        alphas[index] = 1 - t;
      }
      positions[ix] = particle.origin.x;
      positions[ix + 1] = particle.origin.y;
      positions[ix + 2] = particle.origin.z;
    }
    geometry.attributes.position.needsUpdate = true;
    geometry.attributes.aScale.needsUpdate = true;
    geometry.attributes.aAlpha.needsUpdate = true;
  }

  reset();

  return {
    points,
    geometry,
    material,
    particles,
    positions,
    scales,
    alphas,
    reset,
    spawn,
    update,
  };
}

function createBubbleField({
  parent,
  count = 120,
  color = 0xd8f5ff,
  size = 0.24,
  opacity = 0.82,
  name = 'bubble-field',
  spread = new THREE.Vector3(0.7, 0.12, 0.7),
  velocity = new THREE.Vector3(0.12, 0.45, 0.12),
  lifetime = [0.45, 1.1],
  container = null,
  radiusPadding = 0.04,
  yPadding = 0.04,
} = {}) {
  const texture = createSoftCircleTexture({
    inner: 'rgba(255,255,255,0.96)',
    middle: 'rgba(196,239,255,0.78)',
    outer: 'rgba(127,205,255,0)',
  });
  const pool = createParticlePool({ parent, count, texture, color, size, opacity, name });

  function burst(origin, intensity = 1, dt = 1 / 60) {
    const amount = Math.max(0, Math.round((3 + intensity * 14) * dt * 30));
    for (let index = 0; index < amount; index += 1) {
      pool.spawn({
        origin,
        spread,
        velocity: new THREE.Vector3(velocity.x, velocity.y + intensity * 0.55, velocity.z),
        lifetime,
      });
    }
  }

  function update(dt = 1 / 60, elapsed = 0) {
    pool.update(dt, (particle, t, index) => {
      particle.origin.addScaledVector(particle.velocity, dt);
      particle.velocity.y += dt * 0.2;
      particle.velocity.x *= 0.98;
      particle.velocity.z *= 0.98;
      if (container) {
        clampParticleToReactionZone({
          particle,
          pool,
          zone: container,
          radiusPadding,
          yPadding,
        });
      }
      pool.scales[index] = (1 - t) * (0.55 + Math.sin((index + elapsed) * 1.7) * 0.08);
      pool.alphas[index] = 1 - t;
    });
  }

  return { ...pool, burst, update };
}

function createSteamField({
  parent,
  count = 120,
  color = 0xffffff,
  size = 1.1,
  opacity = 0.28,
  name = 'steam-field',
} = {}) {
  const texture = createSoftCircleTexture({
    inner: 'rgba(255,255,255,0.78)',
    middle: 'rgba(220,230,235,0.36)',
    outer: 'rgba(220,230,235,0)',
  });
  const pool = createParticlePool({ parent, count, texture, color, size, opacity, name });

  function burst(origin, intensity = 1, dt = 1 / 60) {
    const amount = Math.max(0, Math.round((2 + intensity * 10) * dt * 26));
    for (let index = 0; index < amount; index += 1) {
      pool.spawn({
        origin,
        spread: new THREE.Vector3(1.2, 0.28, 1.2),
        velocity: new THREE.Vector3(0.18, 0.26 + intensity * 0.32, 0.18),
        lifetime: [1.5, 3.2],
      });
    }
  }

  function update(dt = 1 / 60, elapsed = 0) {
    pool.update(dt, (particle, t, index) => {
      particle.origin.addScaledVector(particle.velocity, dt);
      particle.origin.x += Math.sin(elapsed * 0.9 + index) * dt * 0.08;
      particle.origin.z += Math.cos(elapsed * 0.7 + index * 0.7) * dt * 0.08;
      pool.scales[index] = 0.8 + t * 1.8;
      pool.alphas[index] = (1 - t) * 0.6;
    });
  }

  return { ...pool, burst, update };
}

function createSparkField({
  parent,
  count = 72,
  color = 0xffb84f,
  size = 0.18,
  opacity = 0.72,
  name = 'spark-field',
} = {}) {
  const texture = createSoftCircleTexture({
    inner: 'rgba(255,247,212,1)',
    middle: 'rgba(255,184,79,0.84)',
    outer: 'rgba(255,184,79,0)',
  });
  const pool = createParticlePool({
    parent,
    count,
    texture,
    color,
    size,
    opacity,
    blending: THREE.AdditiveBlending,
    name,
  });

  function burst(origin, intensity = 1, dt = 1 / 60) {
    const amount = Math.max(0, Math.round((0.4 + intensity * 3.2) * dt * 18));
    for (let index = 0; index < amount; index += 1) {
      pool.spawn({
        origin,
        spread: new THREE.Vector3(0.8, 0.12, 0.8),
        velocity: new THREE.Vector3(0.35, 0.35 + intensity * 0.32, 0.35),
        lifetime: [0.25, 0.6],
      });
    }
  }

  function update(dt = 1 / 60) {
    pool.update(dt, (particle, t, index) => {
      particle.origin.addScaledVector(particle.velocity, dt);
      particle.velocity.y -= dt * 0.7;
      pool.scales[index] = (1 - t) * 0.85;
      pool.alphas[index] = (1 - t) * 0.9;
    });
  }

  return { ...pool, burst, update };
}

function resolveWorldPosition(target, out = new THREE.Vector3()) {
  if (typeof target?.getWorldPosition === 'function') {
    return target.getWorldPosition(out);
  }
  if (target?.isVector3) {
    return out.copy(target);
  }
  return out.set(0, 0, 0);
}

function worldToParentLocal(parent, point, out = new THREE.Vector3()) {
  out.copy(point);
  if (typeof parent?.worldToLocal === 'function') {
    parent.worldToLocal(out);
  }
  return out;
}

function placeSegment(mesh, from, to, radiusScale = 1) {
  const direction = new THREE.Vector3().subVectors(to, from);
  const length = direction.length();
  if (length <= 0.0001) {
    mesh.visible = false;
    return false;
  }

  const midpoint = new THREE.Vector3().copy(from).lerp(to, 0.5);
  mesh.position.copy(midpoint);
  mesh.scale.set(radiusScale, length, radiusScale);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), direction.normalize());
  mesh.visible = true;
  return true;
}

function createPourStream({
  parent,
  color = 0xbcecff,
  radius = 0.055,
  opacity = 0.72,
  emissive = 0x67d8ff,
  name = 'pour-stream',
  segmentCount = 6,
} = {}) {
  const material = new THREE.MeshPhysicalMaterial({
    color,
    transparent: true,
    opacity,
    emissive,
    emissiveIntensity: 0.18,
    roughness: 0.18,
    transmission: 0.16,
    depthWrite: false,
  });

  const mesh = new THREE.Group();
  mesh.name = name;
  mesh.visible = false;
  mesh.material = material;
  parent?.add(mesh);

  const droplets = [];
  const segments = [];
  const pointCount = Math.max(4, segmentCount + 1);
  const localPoints = Array.from({ length: pointCount }, () => new THREE.Vector3());
  const worldPoints = Array.from({ length: pointCount }, () => new THREE.Vector3());
  const start = new THREE.Vector3();
  const end = new THREE.Vector3();
  const control1 = new THREE.Vector3();
  const control2 = new THREE.Vector3();
  const temp = new THREE.Vector3();
  const curve = new THREE.CubicBezierCurve3();

  for (let index = 0; index < pointCount; index += 1) {
    const droplet = new THREE.Mesh(
      new THREE.SphereGeometry(radius, 12, 12),
      material,
    );
    droplet.castShadow = false;
    droplet.visible = false;
    droplets.push(droplet);
    mesh.add(droplet);
  }

  for (let index = 0; index < pointCount - 1; index += 1) {
    const segment = new THREE.Mesh(
      new THREE.CylinderGeometry(radius * 0.72, radius * 0.92, 1, 12),
      material,
    );
    segment.castShadow = false;
    segment.visible = false;
    segments.push(segment);
    mesh.add(segment);
  }

  function setEndpoints(source, target, intensity = 1) {
    resolveWorldPosition(source, start);
    resolveWorldPosition(target, end);

    const verticalDrop = Math.max(0.12, start.y - end.y);
    const horizontal = temp.subVectors(end, start).setY(0).length();
    if (verticalDrop <= 0.02 || intensity <= 0.01) {
      reset();
      return false;
    }

    control1.copy(start);
    control1.y = start.y - Math.max(0.08, Math.min(0.16, verticalDrop * 0.24));
    control2.copy(end);
    control2.y = end.y + Math.max(0.24, (verticalDrop * 0.78) + (horizontal * 0.22));

    curve.v0.copy(start);
    curve.v1.copy(control1);
    curve.v2.copy(control2);
    curve.v3.copy(end);

    for (let index = 0; index < pointCount; index += 1) {
      const t = index / (pointCount - 1);
      curve.getPoint(t, worldPoints[index]);
      worldToParentLocal(parent, worldPoints[index], localPoints[index]);
    }

    for (let index = 0; index < droplets.length; index += 1) {
      const droplet = droplets[index];
      const sizeFactor = THREE.MathUtils.lerp(0.62, 1.08, Math.sin((index / Math.max(1, droplets.length - 1)) * Math.PI));
      droplet.position.copy(localPoints[index]);
      droplet.scale.setScalar(Math.max(0.16, intensity) * sizeFactor);
      droplet.visible = true;
    }

    for (let index = 0; index < segments.length; index += 1) {
      const scaleFactor = THREE.MathUtils.lerp(0.56, 0.98, 1 - Math.abs(((index + 0.5) / segments.length) - 0.5) * 1.2);
      placeSegment(segments[index], localPoints[index], localPoints[index + 1], Math.max(0.14, intensity) * scaleFactor);
    }

    material.opacity = opacity * Math.min(1, intensity);
    material.emissiveIntensity = 0.08 + (0.14 * Math.min(1, intensity));
    mesh.visible = true;
    return true;
  }

  function reset() {
    mesh.visible = false;
    for (const droplet of droplets) {
      droplet.visible = false;
      droplet.scale.setScalar(1);
    }
    for (const segment of segments) {
      segment.visible = false;
      segment.scale.set(1, 1, 1);
      segment.quaternion.identity();
    }
  }

  return { mesh, setEndpoints, reset };
}

function createGlowRing({
  parent,
  radius = 1.2,
  tube = 0.05,
  color = 0x73d7ff,
  opacity = 0.22,
  name = 'glow-ring',
  maxOuterRadius = null,
} = {}) {
  const effectiveTube = Math.max(0.001, tube);
  const effectiveRadius = Number.isFinite(maxOuterRadius)
    ? Math.max(0.001, Math.min(radius, maxOuterRadius - effectiveTube))
    : radius;
  const mesh = new THREE.Mesh(
    new THREE.TorusGeometry(effectiveRadius, effectiveTube, 12, 60),
    new THREE.MeshBasicMaterial({
      color,
      transparent: true,
      opacity: 0,
      side: THREE.DoubleSide,
    }),
  );
  mesh.name = name;
  mesh.rotation.x = Math.PI / 2;
  parent?.add(mesh);

  function setIntensity(intensity = 0, elapsed = 0) {
    const value = Math.max(0, Math.min(1, intensity));
    mesh.material.opacity = value <= 0 ? 0 : opacity * value + Math.sin(elapsed * 6.2) * 0.03 * value;
    mesh.scale.setScalar(1 + value * 0.1);
  }

  function reset() {
    mesh.material.opacity = 0;
    mesh.scale.setScalar(1);
  }

  return { mesh, setIntensity, reset, radius: effectiveRadius, tube: effectiveTube, maxOuterRadius };
}

function createFlamePlume({
  parent,
  color = 0x5fd8ff,
  coreColor = 0xd8fbff,
  height = 0.72,
  radius = 0.16,
  opacity = 0.86,
  name = 'flame-plume',
} = {}) {
  const group = new THREE.Group();
  group.name = name;
  group.visible = false;
  parent?.add(group);

  const outer = new THREE.Mesh(
    new THREE.ConeGeometry(radius, height, 28),
    new THREE.MeshBasicMaterial({
      color,
      transparent: true,
      opacity: 0,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    }),
  );
  outer.position.y = height * 0.5;
  group.add(outer);

  const core = new THREE.Mesh(
    new THREE.ConeGeometry(radius * 0.48, height * 0.72, 24),
    new THREE.MeshBasicMaterial({
      color: coreColor,
      transparent: true,
      opacity: 0,
      blending: THREE.AdditiveBlending,
      depthWrite: false,
    }),
  );
  core.position.y = height * 0.36;
  group.add(core);

  function setIntensity(intensity = 0, elapsed = 0) {
    const value = Math.max(0, Math.min(1, intensity));
    group.visible = value > 0.01;
    const flicker = 1 + Math.sin(elapsed * 15.5) * 0.055 + Math.cos(elapsed * 9.1) * 0.035;
    group.scale.set(radius > 0 ? flicker : 1, 1 + value * 0.18, radius > 0 ? 1 / flicker : 1);
    outer.material.opacity = opacity * value;
    core.material.opacity = Math.min(1, (opacity + 0.08) * value);
  }

  function positionAt(target) {
    if (typeof target?.getWorldPosition === 'function') {
      target.getWorldPosition(group.position);
    } else if (target?.isVector3) {
      group.position.copy(target);
    }
  }

  function reset() {
    setIntensity(0, 0);
  }

  return { group, outer, core, setIntensity, positionAt, reset };
}

function createColorTransition({
  material,
  from,
  to,
  property = 'color',
} = {}) {
  const fromColor = new THREE.Color(from ?? material?.[property] ?? 0xffffff);
  const toColor = new THREE.Color(to ?? fromColor);
  const scratch = new THREE.Color();

  function setProgress(progress = 0) {
    const value = Math.max(0, Math.min(1, progress));
    if (!material?.[property]?.copy) {
      return value;
    }
    scratch.copy(fromColor).lerp(toColor, value);
    material[property].copy(scratch);
    return value;
  }

  function reset() {
    setProgress(0);
  }

  return { setProgress, reset, fromColor, toColor };
}

function createMaterialProgress({
  material,
  opacityFrom = material?.opacity ?? 1,
  opacityTo = opacityFrom,
  emissiveIntensityFrom = material?.emissiveIntensity ?? 0,
  emissiveIntensityTo = emissiveIntensityFrom,
} = {}) {
  function setProgress(progress = 0) {
    const value = Math.max(0, Math.min(1, progress));
    if (material) {
      if ('opacity' in material) {
        material.opacity = opacityFrom + (opacityTo - opacityFrom) * value;
      }
      if ('emissiveIntensity' in material) {
        material.emissiveIntensity = emissiveIntensityFrom
          + (emissiveIntensityTo - emissiveIntensityFrom) * value;
      }
    }
    return value;
  }

  function reset() {
    setProgress(0);
  }

  return { setProgress, reset };
}

function createSmokeField({
  parent,
  count = 150,
  color = 0x9aa0a6,
  size = 1.15,
  opacity = 0.34,
  spread = [0.7, 0.12, 0.7],
  velocity = [0.14, 0.16, 0.14],
  lifetime = [2.2, 4.6],
  driftStrength = 0.1,
  scaleRange = [0.55, 2.95],
  alphaRange = [0.58, 0.08],
  name = 'smoke-field',
} = {}) {
  const texture = createSoftCircleTexture({
    inner: 'rgba(238,238,232,0.58)',
    middle: 'rgba(128,134,142,0.34)',
    outer: 'rgba(50,55,62,0)',
  });
  const pool = createParticlePool({ parent, count, texture, color, size, opacity, name });
  const spreadVector = new THREE.Vector3(...spread);
  const velocityVector = new THREE.Vector3(...velocity);

  function burst(origin, intensity = 1, dt = 1 / 60) {
    const amount = Math.max(0, Math.round((2 + intensity * 9) * dt * 24));
    for (let index = 0; index < amount; index += 1) {
      pool.spawn({
        origin,
        spread: spreadVector,
        velocity: new THREE.Vector3(
          velocityVector.x,
          velocityVector.y + intensity * velocityVector.y * 1.5,
          velocityVector.z,
        ),
        lifetime,
      });
    }
  }

  function update(dt = 1 / 60, elapsed = 0) {
    pool.update(dt, (particle, t, index) => {
      particle.origin.addScaledVector(particle.velocity, dt);
      particle.origin.x += Math.sin(elapsed * 0.55 + index * 0.7) * dt * driftStrength;
      particle.origin.z += Math.cos(elapsed * 0.42 + index * 0.5) * dt * driftStrength;
      particle.velocity.y *= 0.992;
      pool.scales[index] = scaleRange[0] + t * Math.max(0.01, scaleRange[1] - scaleRange[0]);
      pool.alphas[index] = (1 - t) * (alphaRange[0] + Math.sin(index) * alphaRange[1]);
    });
  }

  return { ...pool, burst, update };
}

function createContainedGasField({
  parent,
  count = 96,
  color = 0xdce870,
  size = 0.16,
  opacity = 0.28,
  name = 'contained-gas-field',
  radius = 0.28,
  halfHeight = 0.46,
  visualPadding = size * 0.7,
  scaleFrom = 0.36,
  scaleTo = 0.74,
  emitRate = 22,
  rise = 0.035,
  texture = null,
  textureOptions = {},
} = {}) {
  const gasTexture = texture || createSoftCircleTexture({
    inner: 'rgba(245,248,184,0.34)',
    middle: 'rgba(216,232,106,0.18)',
    outer: 'rgba(216,232,106,0)',
    ...textureOptions,
  });
  const pool = createParticlePool({ parent, count, texture: gasTexture, color, size, opacity, name });
  const lastCenter = new THREE.Vector3();

  function clampToVessel(particle, center) {
    const safeRadius = Math.max(0.01, radius - visualPadding);
    const safeHalfHeight = Math.max(0.01, halfHeight - visualPadding);
    const dx = particle.origin.x - center.x;
    const dz = particle.origin.z - center.z;
    const radial = Math.hypot(dx, dz);
    if (radial > safeRadius) {
      const scale = safeRadius / Math.max(radial, 0.001);
      particle.origin.x = center.x + dx * scale;
      particle.origin.z = center.z + dz * scale;
    }
    particle.origin.y = Math.max(center.y - safeHalfHeight, Math.min(center.y + safeHalfHeight, particle.origin.y));
  }

  function emit(origin, intensity = 0.3, dt = 1 / 60) {
    lastCenter.copy(origin);
    const amount = Math.max(0, Math.round((1 + intensity * 6) * dt * emitRate));
    for (let index = 0; index < amount; index += 1) {
      const particle = pool.spawn({
        origin,
        spread: new THREE.Vector3(Math.max(0.01, radius - visualPadding) * 1.7, Math.max(0.01, halfHeight - visualPadding), Math.max(0.01, radius - visualPadding) * 1.7),
        velocity: new THREE.Vector3(0.028, rise + intensity * 0.035, 0.028),
        lifetime: [1.2, 2.6],
      });
      if (particle) {
        clampToVessel(particle, lastCenter);
      }
    }
  }

  function update(dt = 1 / 60, elapsed = 0, center = lastCenter) {
    lastCenter.copy(center);
    pool.update(dt, (particle, t, index) => {
      particle.origin.addScaledVector(particle.velocity, dt);
      particle.origin.x += Math.sin(elapsed * 0.7 + index * 0.41) * dt * 0.035;
      particle.origin.z += Math.cos(elapsed * 0.62 + index * 0.37) * dt * 0.035;
      clampToVessel(particle, lastCenter);
      particle.velocity.y *= 0.988;
      pool.scales[index] = scaleFrom + t * (scaleTo - scaleFrom);
      pool.alphas[index] = (1 - t) * 0.72;
    });
  }

  return { ...pool, emit, update };
}

function resolveZoneObject(zone) {
  return zone?.object || zone?.group || zone?.apparatus?.group || null;
}

function resolveZoneValue(value, fallback) {
  return typeof value === 'function' ? value() : value ?? fallback;
}

function resolveZoneRadius(zone) {
  const apparatus = zone?.apparatus || null;
  const baseRadius = apparatus?.constraints?.innerRadius ?? 0.5;
  const radiusScale = resolveZoneValue(zone?.radiusScale, 1);
  const radiusPadding = resolveZoneValue(zone?.radiusPadding, 0);
  return Math.max(0.001, resolveZoneValue(zone?.radius, baseRadius * radiusScale) - radiusPadding);
}

function resolveZoneMinY(zone) {
  return resolveZoneValue(zone?.minY, 0);
}

function resolveZoneMaxY(zone) {
  const apparatus = zone?.apparatus || null;
  const minY = resolveZoneMinY(zone);
  const fillHeight = apparatus?.state?.fillHeight;
  const fallbackMax = apparatus?.constraints?.safeFillHeight
    ?? apparatus?.constraints?.innerHeight
    ?? apparatus?.anchors?.mouth?.position?.y
    ?? 1;
  const headroom = resolveZoneValue(zone?.headroom, zone?.liquidOnly ? 0.03 : 0.08);
  const maxY = zone?.liquidOnly && Number.isFinite(fillHeight)
    ? fillHeight + headroom
    : resolveZoneValue(zone?.maxY, fallbackMax + headroom);
  return Math.max(minY + 0.001, maxY);
}

function createVesselReactionZone({
  apparatus = null,
  object = null,
  group = null,
  name = 'vessel-reaction-zone',
  radius = null,
  radiusScale = 0.92,
  radiusPadding = 0,
  minY = 0,
  maxY = null,
  headroom = null,
  liquidOnly = false,
} = {}) {
  const zone = {
    name,
    apparatus,
    object: object || group || apparatus?.group || null,
    radius,
    radiusScale,
    radiusPadding,
    minY,
    maxY,
    headroom,
    liquidOnly,
  };

  zone.getRadius = () => resolveZoneRadius(zone);
  zone.getMinY = () => resolveZoneMinY(zone);
  zone.getMaxY = () => resolveZoneMaxY(zone);
  return zone;
}

function reactionZoneContainsLocalPoint(zone, localPoint, {
  radiusPadding = 0,
  yPadding = 0,
} = {}) {
  if (!zone || !localPoint) {
    return true;
  }
  const radius = Math.max(0.001, resolveZoneRadius(zone) - radiusPadding);
  const minY = resolveZoneMinY(zone) + yPadding;
  const maxY = resolveZoneMaxY(zone) - yPadding;
  return Math.hypot(localPoint.x, localPoint.z) <= radius
    && localPoint.y >= minY
    && localPoint.y <= maxY;
}

function clampLocalPointToReactionZone(zone, localPoint, {
  radiusPadding = 0,
  yPadding = 0,
} = {}) {
  const result = {
    ok: true,
    radial: false,
    minY: false,
    maxY: false,
  };
  if (!zone || !localPoint) {
    return result;
  }

  const radius = Math.max(0.001, resolveZoneRadius(zone) - radiusPadding);
  const minY = resolveZoneMinY(zone) + yPadding;
  const maxY = resolveZoneMaxY(zone) - yPadding;
  const radialDistance = Math.hypot(localPoint.x, localPoint.z);
  if (radialDistance > radius) {
    const scale = radius / Math.max(radialDistance, 0.001);
    localPoint.x *= scale;
    localPoint.z *= scale;
    result.radial = true;
    result.ok = false;
  }
  if (localPoint.y < minY) {
    localPoint.y = minY;
    result.minY = true;
    result.ok = false;
  }
  if (localPoint.y > maxY) {
    localPoint.y = maxY;
    result.maxY = true;
    result.ok = false;
  }
  return result;
}

function reactionZoneWorldToLocal(zone, worldPoint, out = new THREE.Vector3()) {
  const object = resolveZoneObject(zone);
  out.copy(worldPoint);
  if (object?.worldToLocal) {
    object.worldToLocal(out);
  }
  return out;
}

function reactionZoneLocalToWorld(zone, localPoint, out = new THREE.Vector3()) {
  const object = resolveZoneObject(zone);
  out.copy(localPoint);
  if (object?.localToWorld) {
    object.localToWorld(out);
  }
  return out;
}

function clampParticleToReactionZone({
  particle,
  pool,
  zone,
  radiusPadding = 0,
  yPadding = 0,
} = {}) {
  const object = resolveZoneObject(zone);
  if (!particle || !object?.worldToLocal || !object?.localToWorld) {
    return { ok: true, radial: false, minY: false, maxY: false };
  }

  const world = particle.origin.clone();
  pool?.points?.parent?.localToWorld?.(world);
  object.worldToLocal(world);
  const result = clampLocalPointToReactionZone(zone, world, { radiusPadding, yPadding });
  object.localToWorld(world);
  pool?.points?.parent?.worldToLocal?.(world);
  particle.origin.copy(world);
  return result;
}

function particlePoolContainedInReactionZone(pool, zone, {
  activeOnly = true,
  radiusPadding = 0,
  yPadding = 0,
} = {}) {
  const object = resolveZoneObject(zone);
  if (!pool?.particles || !object?.worldToLocal) {
    return true;
  }

  const world = new THREE.Vector3();
  const local = new THREE.Vector3();
  return pool.particles.every((particle) => {
    if (activeOnly && !particle.active) {
      return true;
    }
    world.copy(particle.origin);
    pool.points?.parent?.localToWorld?.(world);
    object.worldToLocal(local.copy(world));
    return reactionZoneContainsLocalPoint(zone, local, { radiusPadding, yPadding });
  });
}

function objectContainedInReactionZone(objectOrApparatus, zone, {
  present = true,
  radiusPadding = 0,
  yPadding = 0,
} = {}) {
  if (!present) {
    return true;
  }

  const object = objectOrApparatus?.group || objectOrApparatus;
  const zoneObject = resolveZoneObject(zone);
  if (!object || !zoneObject?.worldToLocal) {
    return true;
  }

  const box = new THREE.Box3().setFromObject(object);
  if (box.isEmpty()) {
    return true;
  }

  const center = new THREE.Vector3();
  const size = new THREE.Vector3();
  box.getCenter(center);
  box.getSize(size);
  zoneObject.worldToLocal(center);

  const radialHalfExtent = Math.max(size.x, size.z) * 0.5;
  const verticalHalfExtent = size.y * 0.5;
  return reactionZoneContainsLocalPoint(zone, center, {
    radiusPadding: radiusPadding + radialHalfExtent,
    yPadding: yPadding + verticalHalfExtent,
  });
}

function createPrecipitateCloud({
  parent,
  count = 170,
  color = 0xf0da78,
  size = 0.16,
  opacity = 0.72,
  name = 'precipitate-cloud',
} = {}) {
  const texture = createSoftCircleTexture({
    inner: 'rgba(255,246,190,0.92)',
    middle: 'rgba(230,199,94,0.66)',
    outer: 'rgba(230,199,94,0)',
  });
  const pool = createParticlePool({ parent, count, texture, color, size, opacity, name });

  function burst(origin, intensity = 1, dt = 1 / 60) {
    const amount = Math.max(0, Math.round((3 + intensity * 12) * dt * 24));
    for (let index = 0; index < amount; index += 1) {
      pool.spawn({
        origin,
        spread: new THREE.Vector3(0.72, 0.38, 0.72),
        velocity: new THREE.Vector3(0.06, 0.05 + intensity * 0.04, 0.06),
        lifetime: [2.4, 5.2],
      });
    }
  }

  function update(dt = 1 / 60, elapsed = 0) {
    pool.update(dt, (particle, t, index) => {
      particle.origin.addScaledVector(particle.velocity, dt);
      particle.origin.x += Math.sin(elapsed * 1.2 + index) * dt * 0.035;
      particle.origin.z += Math.cos(elapsed * 1.0 + index * 0.6) * dt * 0.035;
      particle.velocity.y -= dt * 0.035;
      pool.scales[index] = 0.55 + Math.sin(elapsed * 1.7 + index) * 0.12;
      pool.alphas[index] = Math.max(0, 1 - t * 0.82);
    });
  }

  return { ...pool, burst, update };
}

function createGasCollectionBubbles({
  parent,
  count = 130,
  color = 0xdff8ff,
  size = 0.2,
  opacity = 0.78,
  name = 'gas-collection-bubbles',
} = {}) {
  const texture = createSoftCircleTexture({
    inner: 'rgba(255,255,255,0.96)',
    middle: 'rgba(192,238,255,0.72)',
    outer: 'rgba(116,202,255,0)',
  });
  const pool = createParticlePool({ parent, count, texture, color, size, opacity, name });
  const source = new THREE.Vector3(-0.6, 1.5, 0);
  const target = new THREE.Vector3(0.55, 2.05, 0);

  function setEndpoints(from, to) {
    if (typeof from?.getWorldPosition === 'function') {
      from.getWorldPosition(source);
    } else if (from?.isVector3) {
      source.copy(from);
    }
    if (typeof to?.getWorldPosition === 'function') {
      to.getWorldPosition(target);
    } else if (to?.isVector3) {
      target.copy(to);
    }
  }

  function burst(origin = source, intensity = 1, dt = 1 / 60) {
    const direction = target.clone().sub(source).normalize();
    const amount = Math.max(0, Math.round((2 + intensity * 10) * dt * 26));
    for (let index = 0; index < amount; index += 1) {
      const particle = pool.spawn({
        origin,
        spread: new THREE.Vector3(0.14, 0.1, 0.14),
        velocity: new THREE.Vector3(0.02, 0.02, 0.02),
        lifetime: [0.9, 1.8],
      });
      if (particle) {
        particle.velocity.copy(direction).multiplyScalar(0.42 + intensity * 0.55);
        particle.velocity.y += 0.1 + intensity * 0.14;
      }
    }
  }

  function update(dt = 1 / 60, elapsed = 0) {
    pool.update(dt, (particle, t, index) => {
      particle.origin.addScaledVector(particle.velocity, dt);
      particle.origin.x += Math.sin(elapsed * 2.2 + index) * dt * 0.05;
      particle.origin.z += Math.cos(elapsed * 2 + index * 0.4) * dt * 0.05;
      particle.velocity.y += dt * 0.05;
      pool.scales[index] = (1 - t) * (0.6 + t * 0.7);
      pool.alphas[index] = 1 - t;
    });
  }

  return { ...pool, source, target, setEndpoints, burst, update };
}

function createHeatShimmer({
  parent,
  radius = 0.42,
  height = 0.85,
  color = 0xffd18a,
  opacity = 0.2,
  name = 'heat-shimmer',
} = {}) {
  const group = new THREE.Group();
  group.name = name;
  group.visible = false;
  parent?.add(group);

  const material = new THREE.MeshBasicMaterial({
    color,
    transparent: true,
    opacity: 0,
    depthWrite: false,
    side: THREE.DoubleSide,
    blending: THREE.AdditiveBlending,
  });

  const ribbons = [];
  for (let index = 0; index < 4; index += 1) {
    const ribbon = new THREE.Mesh(new THREE.PlaneGeometry(radius * 0.42, height, 8, 1), material.clone());
    ribbon.position.y = height * 0.5;
    ribbon.rotation.y = (Math.PI / 4) * index;
    ribbon.userData.phase = index * 1.7;
    group.add(ribbon);
    ribbons.push(ribbon);
  }

  function setIntensity(intensity = 0, elapsed = 0) {
    const value = Math.max(0, Math.min(1, intensity));
    group.visible = value > 0.01;
    for (const ribbon of ribbons) {
      const wave = Math.sin(elapsed * 4.2 + ribbon.userData.phase);
      ribbon.scale.set(1 + wave * 0.18, 1 + value * 0.22, 1);
      ribbon.position.x = Math.sin(elapsed * 2.5 + ribbon.userData.phase) * radius * 0.08;
      ribbon.material.opacity = opacity * value * (0.72 + wave * 0.16);
    }
  }

  function positionAt(target) {
    if (typeof target?.getWorldPosition === 'function') {
      target.getWorldPosition(group.position);
    } else if (target?.isVector3) {
      group.position.copy(target);
    }
  }

  function reset() {
    setIntensity(0, 0);
  }

  return { group, ribbons, setIntensity, positionAt, reset };
}

function createReactionFlow({
  id = 'reaction-flow',
  duration = 2,
  initialPhase = 'idle',
  successPhase = 'result',
  autoplayStep = 'run-reaction-autoplay',
  effects = [],
  status = {},
  onStart,
  onUpdate,
  onAfterFinishUpdate,
  onFinish,
  onReset,
} = {}) {
  const state = {
    id,
    phase: initialPhase,
    t: 0,
    progress: 0,
    mode: null,
    hasManualResult: false,
    hasAutoplayResult: false,
  };

  function start(mode = 'manual') {
    state.phase = 'reaction';
    state.t = 0;
    state.progress = 0;
    state.mode = mode;
    state.hasManualResult = mode === 'manual';
    state.hasAutoplayResult = mode === 'autoplay';
    onStart?.({ state, mode });
    return true;
  }

  function finish() {
    state.phase = successPhase;
    state.progress = 1;
    for (const effect of effects) {
      effect.setProgress?.(1);
    }
    onFinish?.({ state });
    return true;
  }

  function update(dt = 1 / 60, elapsed = performance.now() / 1000) {
    if (state.phase !== 'reaction') {
      if (state.phase === successPhase) {
        onAfterFinishUpdate?.({ state, dt, elapsed });
      }
      return state;
    }

    state.t += dt;
    state.progress = Math.min(1, state.t / Math.max(duration, 0.001));
    for (const effect of effects) {
      effect.setProgress?.(state.progress, elapsed, state);
    }
    onUpdate?.({ state, dt, elapsed });

    if (state.progress >= 1) {
      finish();
    }
    return state;
  }

  function reset() {
    state.phase = initialPhase;
    state.t = 0;
    state.progress = 0;
    state.mode = null;
    state.hasManualResult = false;
    state.hasAutoplayResult = false;
    for (const effect of effects) {
      effect.reset?.();
    }
    onReset?.({ state });
    return true;
  }

  function autoplay() {
    return start('autoplay');
  }

  return {
    id,
    state,
    status,
    start,
    autoplay,
    update,
    finish,
    reset,
    getState() {
      return { ...state };
    },
    getVerifierMeta() {
      return { successPhase, supportsGoldenPath: true };
    },
    getGoldenPath() {
      return [{ type: autoplayStep, afterMs: Math.round(duration * 1000 + 250) }];
    },
    runVerifierStep(step) {
      if (step?.type === autoplayStep || step?.type === 'run-autoplay') {
        autoplay();
        state.t = duration;
        state.progress = 1;
        finish();
        return true;
      }
      return false;
    },
  };
}

function anchorOf(apparatus, preferred) {
  return apparatus?.anchors?.[preferred] || apparatus?.group || apparatus;
}

function createPourIntoVesselReaction({
  id = 'pour-into-vessel',
  source,
  target,
  stream,
  duration = 1.4,
  onPourStart,
  onPourUpdate,
  onPourFinish,
} = {}) {
  const flow = createReactionFlow({
    id,
    duration,
    effects: [stream].filter(Boolean),
    onStart(context) {
      onPourStart?.(context);
    },
    onUpdate({ state, dt, elapsed }) {
      const sourceAnchor = anchorOf(source, 'nozzle');
      const targetAnchor = anchorOf(target, 'mouth');
      stream?.setEndpoints?.(sourceAnchor, targetAnchor, Math.max(0.15, state.progress));
      onPourUpdate?.({ state, dt, elapsed });
    },
    onFinish(context) {
      stream?.reset?.();
      onPourFinish?.(context);
    },
    onReset() {
      stream?.reset?.();
    },
  });

  function isAligned(maxDistance = target?.constraints?.safePourRadius ?? 0.5) {
    const sourcePoint = anchorOf(source, 'nozzle').getWorldPosition?.(new THREE.Vector3()) ?? new THREE.Vector3();
    const targetPoint = anchorOf(target, 'mouth').getWorldPosition?.(new THREE.Vector3()) ?? new THREE.Vector3();
    sourcePoint.y = targetPoint.y;
    return sourcePoint.distanceTo(targetPoint) <= maxDistance;
  }

  return { ...flow, isAligned };
}

const indicatorOutcomes = {
  acid: { state: 'acid-contact', color: 'red' },
  base: { state: 'base-contact', color: 'blue' },
  neutral: { state: 'neutral-contact', color: 'purple' },
};

function createAcidBaseIndicatorReaction({
  indicator,
  getSolutionType,
  duration = 0.8,
  onContact,
} = {}) {
  return createReactionFlow({
    id: 'acid-base-indicator',
    duration,
    onStart({ state }) {
      const solutionType = getSolutionType?.() || 'neutral';
      const outcome = indicatorOutcomes[solutionType] || indicatorOutcomes.neutral;
      indicator?.controllers?.setIndicatorState?.(outcome.state);
      indicator?.setIndicatorState?.(outcome.state);
      state.solutionType = solutionType;
      state.outcomeColor = outcome.color;
      onContact?.({ solutionType, outcome, state });
    },
    onReset() {
      indicator?.controllers?.setIndicatorState?.('ready');
      indicator?.setIndicatorState?.('ready');
    },
  });
}

function createMetalDisplacementReaction({
  metalSample,
  solution,
  bubbleField = null,
  depositEffects = [],
  duration = 1.85,
  solutionFrom = 0x3f87df,
  solutionTo = 0xbfd8f5,
} = {}) {
  const fromColor = new THREE.Color(solutionFrom);
  const toColor = new THREE.Color(solutionTo);
  const scratch = new THREE.Color();
  const effectOrigin = new THREE.Vector3();

  return createReactionFlow({
    id: 'metal-displacement',
    duration,
    effects: [bubbleField, ...depositEffects].filter(Boolean),
    onUpdate({ state, dt, elapsed }) {
      const progress = state.progress;
      metalSample?.controllers?.setCopperCoating?.(progress);
      if (solution?.material?.color) {
        scratch.copy(fromColor).lerp(toColor, progress);
        solution.material.color.copy(scratch);
      }
      const source = metalSample?.anchors?.effectOrigin || metalSample?.group;
      if (typeof source?.getWorldPosition === 'function') {
        source.getWorldPosition(effectOrigin);
      } else if (source?.isVector3) {
        effectOrigin.copy(source);
      }
      bubbleField?.burst?.(effectOrigin, progress, dt);
      bubbleField?.update?.(dt, elapsed);
      for (const effect of depositEffects) {
        effect.setProgress?.(progress, elapsed, state);
      }
    },
    onReset() {
      metalSample?.controllers?.setCopperCoating?.(0);
      if (solution?.material?.color) {
        solution.material.color.copy(fromColor);
      }
    },
  });
}

function getDehydrationWorldPosition(target, out = new THREE.Vector3()) {
  if (typeof target?.getWorldPosition === 'function') {
    return target.getWorldPosition(out);
  }
  if (target?.isVector3) {
    return out.copy(target);
  }
  return out.set(0, 0, 0);
}

function createDehydrationCarbonizationReaction({
  sugar,
  carbonMass,
  caramelLayer,
  effectOrigin,
  steamOrigin,
  bubbleField,
  steamField,
  sparkField,
  glowRing,
  duration = 8.5,
} = {}) {
  const sugarStartColor = new THREE.Color(0xf4e6bf);
  const carbonColor = new THREE.Color(0x382110);
  const bubbleCenter = new THREE.Vector3();
  const steamCenter = new THREE.Vector3();

  return createReactionFlow({
    id: 'dehydration-carbonization',
    duration,
    effects: [bubbleField, steamField, sparkField, glowRing].filter(Boolean),
    onUpdate({ state, dt, elapsed }) {
      const heat = Math.min(state.t / 3.5, 1);
      const growth = THREE.MathUtils.smootherstep(state.t, 0.4, duration);
      const pulse = Math.sin(elapsed * 18) * 0.04;

      if (sugar) {
        sugar.scale.y = 1 - growth * 0.92;
        sugar.position.y = -0.84 - growth * 0.26;
        if (sugar.material?.color) {
          sugar.material.color.copy(sugarStartColor).lerp(carbonColor, growth * 0.9);
        }
        if (sugar.material && 'emissiveIntensity' in sugar.material) {
          sugar.material.emissiveIntensity = 0.15 * heat;
        }
      }

      if (caramelLayer) {
        caramelLayer.visible = true;
        caramelLayer.material.opacity = 0.15 + heat * 0.35;
      }

      if (carbonMass) {
        carbonMass.scale.y = 0.1 + growth * 8.8 + pulse;
        carbonMass.scale.x = 1 + growth * 0.38;
        carbonMass.scale.z = 1 + growth * 0.34;
        carbonMass.position.y = -0.58 + carbonMass.scale.y * 0.18;
      }

      glowRing?.setIntensity?.(0.35 + heat * 0.65, elapsed);
      getDehydrationWorldPosition(effectOrigin, bubbleCenter).add(new THREE.Vector3(0, growth * 1.2, 0));
      getDehydrationWorldPosition(steamOrigin || effectOrigin, steamCenter).add(new THREE.Vector3(0, growth * 1.6, 0));
      bubbleField?.burst?.(bubbleCenter, heat, dt);
      steamField?.burst?.(steamCenter, heat, dt);
      sparkField?.burst?.(bubbleCenter, heat, dt);
      bubbleField?.update?.(dt, elapsed);
      steamField?.update?.(dt, elapsed);
      sparkField?.update?.(dt, elapsed);
    },
    onReset() {
      if (sugar) {
        sugar.scale.set(1, 1, 1);
        if (sugar.material?.color) {
          sugar.material.color.copy(sugarStartColor);
        }
      }
      if (carbonMass) {
        carbonMass.scale.setScalar(0.001);
      }
      if (caramelLayer) {
        caramelLayer.visible = false;
        caramelLayer.material.opacity = 0;
      }
    },
  });
}

function getAcidMetalWorldPosition(target, out = new THREE.Vector3()) {
  if (typeof target?.getWorldPosition === 'function') {
    return target.getWorldPosition(out);
  }
  if (target?.isVector3) {
    return out.copy(target);
  }
  return out.set(0, 0, 0);
}

function createAcidMetalGasReaction({
  metalSample,
  vessel,
  bubbleField,
  sparkField,
  solutionColorTransition,
  duration = 2.4,
} = {}) {
  const origin = new THREE.Vector3();

  return createReactionFlow({
    id: 'acid-metal-gas',
    duration,
    effects: [bubbleField, sparkField, solutionColorTransition].filter(Boolean),
    onUpdate({ state, dt, elapsed }) {
      const progress = state.progress;
      getAcidMetalWorldPosition(vessel?.anchors?.effectOrigin || metalSample?.anchors?.effectOrigin || metalSample?.group, origin);
      bubbleField?.burst?.(origin, progress, dt);
      bubbleField?.update?.(dt, elapsed);
      sparkField?.burst?.(origin, Math.max(0, progress - 0.72), dt);
      sparkField?.update?.(dt, elapsed);
      solutionColorTransition?.setProgress?.(progress);
      metalSample?.controllers?.setCorrosionProgress?.(progress);
    },
    onReset() {
      solutionColorTransition?.reset?.();
      metalSample?.controllers?.setCorrosionProgress?.(0);
    },
  });
}

function getMethaneCombustionWorldPosition(target, out = new THREE.Vector3()) {
  if (typeof target?.getWorldPosition === 'function') {
    return target.getWorldPosition(out);
  }
  if (target?.isVector3) {
    return out.copy(target);
  }
  return out.set(0, 0, 0);
}

function createMethaneCombustionReaction({
  vessel,
  ignitionSource,
  bubbleField,
  steamField,
  sparkField,
  glowRing,
  flamePlume,
  duration = 5.2,
} = {}) {
  const gasOrigin = new THREE.Vector3();
  const flameOrigin = new THREE.Vector3();

  function updateCombustionEffects({ progress = 1, dt = 1 / 60, elapsed = 0, sustained = false } = {}) {
    const ignition = sustained ? 1 : Math.max(0, Math.min(1, (progress - 0.18) / 0.82));
    getMethaneCombustionWorldPosition(vessel?.anchors?.effectOrigin || vessel?.group, gasOrigin);
    getMethaneCombustionWorldPosition(vessel?.anchors?.steamOrigin || ignitionSource?.anchors?.flameOrigin || gasOrigin, flameOrigin);

    if (!sustained) {
      bubbleField?.burst?.(gasOrigin, Math.max(0.12, 1 - progress * 0.45), dt);
    }
    bubbleField?.update?.(dt, elapsed);
    steamField?.burst?.(flameOrigin, sustained ? 0.28 : ignition * 0.82, dt);
    steamField?.update?.(dt, elapsed);
    sparkField?.burst?.(flameOrigin, sustained ? 0.12 : (ignition > 0.08 ? ignition : 0), dt);
    sparkField?.update?.(dt, elapsed);
    glowRing?.mesh?.position?.copy?.(flameOrigin);
    glowRing?.setIntensity?.(sustained ? 0.82 : ignition, elapsed);
    flamePlume?.positionAt?.(flameOrigin);
    flamePlume?.setIntensity?.(sustained ? 0.92 : ignition, elapsed);
  }

  return createReactionFlow({
    id: 'methane-combustion',
    duration,
    effects: [bubbleField, steamField, sparkField, glowRing, flamePlume].filter(Boolean),
    onUpdate({ state, dt, elapsed }) {
      updateCombustionEffects({ progress: state.progress, dt, elapsed });
    },
    onAfterFinishUpdate({ dt, elapsed }) {
      updateCombustionEffects({ progress: 1, dt, elapsed, sustained: true });
    },
    onReset() {
      glowRing?.reset?.();
      flamePlume?.reset?.();
    },
  });
}

function getElectrolysisWorldPosition(target, out = new THREE.Vector3()) {
  if (typeof target?.getWorldPosition === 'function') {
    return target.getWorldPosition(out);
  }
  if (target?.isVector3) {
    return out.copy(target);
  }
  return out.set(0, 0, 0);
}

function createWaterElectrolysisReaction({
  electrodePair,
  cathodeBubbleField,
  anodeBubbleField,
  duration = 6.2,
} = {}) {
  const cathodeOrigin = new THREE.Vector3();
  const anodeOrigin = new THREE.Vector3();

  function updateElectrolysisEffects({ progress = 1, dt = 1 / 60, elapsed = 0, sustained = false } = {}) {
    const intensity = sustained ? 0.58 : Math.max(0.12, progress);
    getElectrolysisWorldPosition(electrodePair?.anchors?.cathodeBubbleOrigin || electrodePair?.group, cathodeOrigin);
    getElectrolysisWorldPosition(electrodePair?.anchors?.anodeBubbleOrigin || electrodePair?.group, anodeOrigin);

    cathodeBubbleField?.burst?.(cathodeOrigin, intensity * 1.25, dt);
    cathodeBubbleField?.update?.(dt, elapsed);
    anodeBubbleField?.burst?.(anodeOrigin, intensity * 0.68, dt);
    anodeBubbleField?.update?.(dt, elapsed);
  }

  return createReactionFlow({
    id: 'water-electrolysis',
    duration,
    effects: [cathodeBubbleField, anodeBubbleField].filter(Boolean),
    onStart() {
      electrodePair?.controllers?.setPowered?.(true);
    },
    onUpdate({ state, dt, elapsed }) {
      updateElectrolysisEffects({ progress: state.progress, dt, elapsed });
    },
    onAfterFinishUpdate({ dt, elapsed }) {
      updateElectrolysisEffects({ progress: 1, dt, elapsed, sustained: true });
    },
    onReset() {
      electrodePair?.controllers?.setPowered?.(false);
    },
  });
}

function getCanvasBox(renderer) {
  return renderer.domElement.getBoundingClientRect();
}

function canvasPoint(renderer, nx, ny) {
  const rect = getCanvasBox(renderer);
  return {
    x: rect.left + rect.width * nx,
    y: rect.top + rect.height * ny,
  };
}

function projectWorldToCanvas(target, camera, renderer, offset = new THREE.Vector3()) {
  const rect = getCanvasBox(renderer);
  const anchor = typeof target.getWorldPosition === 'function'
    ? target.getWorldPosition(new THREE.Vector3())
    : target.clone();
  const projected = anchor.add(offset).project(camera);
  return {
    x: rect.left + ((projected.x + 1) * 0.5) * rect.width,
    y: rect.top + ((-projected.y + 1) * 0.5) * rect.height,
  };
}

function installFlameTestHarness({ state, mapState, getPaths }) {
  window.__flameTestApi = {
    getState() {
      return mapState(state);
    },
    ...getPaths(),
  };

  return window.__flameTestApi;
}

function installCoursewareTestHarness({
  state,
  mapState,
  getVerifierMeta,
  getCapabilities,
  getStepContract,
  getGoldenPath,
  getDragPath,
  dragFromPageApi,
  runVerifierStep,
}) {
  window.__coursewareTestApi = {
    getState() {
      return mapState(state);
    },
    getVerifierMeta() {
      return typeof getVerifierMeta === 'function' ? getVerifierMeta(state) : null;
    },
    getCapabilities() {
      return typeof getCapabilities === 'function' ? getCapabilities(state) : null;
    },
    getStepContract() {
      return typeof getStepContract === 'function' ? getStepContract(state) : null;
    },
    getGoldenPath() {
      return typeof getGoldenPath === 'function' ? getGoldenPath(state) : null;
    },
    getDragPath(sampleId) {
      return typeof getDragPath === 'function' ? getDragPath(sampleId, state) : null;
    },
    dragFromPageApi(args) {
      return typeof dragFromPageApi === 'function' ? dragFromPageApi(args, state) : false;
    },
    runVerifierStep(step) {
      return typeof runVerifierStep === 'function' ? runVerifierStep(step, state) : false;
    },
  };

  return window.__coursewareTestApi;
}

